echo "== arms_leadcond_a.txt sha256 $(sha256sum arms_leadcond_a.txt | cut -c1-64) PIN $(grep -c '^PIN|' arms_leadcond_a.txt) ARM $(grep -c '^ARM|' arms_leadcond_a.txt)"; grep '^ARM|' arms_leadcond_a.txt | cut -d'|' -f2,4,5,8 | cut -c1-230
dr() { C2_CARD=PREREG_V8F_PROOF_ADD35 bash chain_arms_ft6.sh dryx arms_leadcond_a.txt --dry-run | grep "^TRAIN $1" | sed -e "s|/runs/[a-z_0-9]*/$1|/runs/X/A|g" -e "s|^TRAIN $1|TRAIN A|"; }
dr LFT_s0 > /tmp/lc_lft.txt; dr LFTb_s0 > /tmp/lc_lftb.txt; dr LC_s0 | sed -e 's| --lead-cond on||' > /tmp/lc_lc.txt
[ -s /tmp/lc_lft.txt ] && cmp -s /tmp/lc_lft.txt /tmp/lc_lftb.txt && echo 'argv of LFTb_s0 equals that of LFT_s0 apart from name and out folder' || echo 'ARGV DIFFERS (LFTb)'
[ -s /tmp/lc_lft.txt ] && cmp -s /tmp/lc_lft.txt /tmp/lc_lc.txt && echo 'argv of LC_s0 equals that of LFT_s0 apart from name, out folder and the flag --lead-cond on' || { echo 'ARGV DIFFERS (LC)'; diff /tmp/lc_lft.txt /tmp/lc_lc.txt | cut -c1-300 | head -n 6; }
